/**
 * One item of a `bulk_compress` result: the input's `index` and its
 * outcome. On success `ok` is true and `report` holds the result;
 * on failure `ok` is false, `report` is `null`, and the error is
 * carried flat in `error_code` / `error_message_en` /
 * `error_message_hi` (see DIVERGENCE note).
 */
public struct BulkItemResult {
    public var index: UInt32
    public var ok: Bool
    public var report: CompressReport?
    public var errorCode: String?
    public var errorMessageEn: String?
    public var errorMessageHi: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(index: UInt32, ok: Bool, report: CompressReport? = nil, errorCode: String? = nil, errorMessageEn: String? = nil, errorMessageHi: String? = nil) {
        self.index = index
        self.ok = ok
        self.report = report
        self.errorCode = errorCode
        self.errorMessageEn = errorMessageEn
        self.errorMessageHi = errorMessageHi
    }
}

