extension BulkItemResult: Equatable, Hashable {
    public static func ==(lhs: BulkItemResult, rhs: BulkItemResult) -> Bool {
        if lhs.index != rhs.index {
            return false
        }
        if lhs.ok != rhs.ok {
            return false
        }
        if lhs.report != rhs.report {
            return false
        }
        if lhs.errorCode != rhs.errorCode {
            return false
        }
        if lhs.errorMessageEn != rhs.errorMessageEn {
            return false
        }
        if lhs.errorMessageHi != rhs.errorMessageHi {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(index)
        hasher.combine(ok)
        hasher.combine(report)
        hasher.combine(errorCode)
        hasher.combine(errorMessageEn)
        hasher.combine(errorMessageHi)
    }
