/**
 * Full before/after report for one compression (SPEC §1).
 * `format` is the OUTPUT format. `saved_percent` is
 * `100 * saved_bytes / original_size` (0 when `original_size` is 0).
 * `quality_used` is the quality the output was actually encoded at
 * (differs from the requested quality after a `compress_to_size`
 * search or a downscale fallback). `resized` is true when the output
 * dimensions differ from the input dimensions.
 */
public struct CompressReport {
    public var output: [UInt8]
    public var originalSize: UInt64
    public var outputSize: UInt64
    public var savedBytes: UInt64
    public var savedPercent: Float
    public var format: ImageFormat
    public var width: UInt32
    public var height: UInt32
    public var qualityUsed: UInt8
    public var resized: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(output: [UInt8], originalSize: UInt64, outputSize: UInt64, savedBytes: UInt64, savedPercent: Float, format: ImageFormat, width: UInt32, height: UInt32, qualityUsed: UInt8, resized: Bool) {
        self.output = output
        self.originalSize = originalSize
        self.outputSize = outputSize
        self.savedBytes = savedBytes
        self.savedPercent = savedPercent
        self.format = format
        self.width = width
        self.height = height
        self.qualityUsed = qualityUsed
        self.resized = resized
    }
}

