    public static func ==(lhs: CompressReport, rhs: CompressReport) -> Bool {
        if lhs.output != rhs.output {
            return false
        }
        if lhs.originalSize != rhs.originalSize {
            return false
        }
        if lhs.outputSize != rhs.outputSize {
            return false
        }
        if lhs.savedBytes != rhs.savedBytes {
            return false
        }
        if lhs.savedPercent != rhs.savedPercent {
            return false
        }
        if lhs.format != rhs.format {
            return false
        }
        if lhs.width != rhs.width {
            return false
        }
        if lhs.height != rhs.height {
            return false
        }
        if lhs.qualityUsed != rhs.qualityUsed {
            return false
        }
        if lhs.resized != rhs.resized {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(output)
        hasher.combine(originalSize)
        hasher.combine(outputSize)
        hasher.combine(savedBytes)
        hasher.combine(savedPercent)
        hasher.combine(format)
        hasher.combine(width)
        hasher.combine(height)
        hasher.combine(qualityUsed)
        hasher.combine(resized)
    }
}



