public enum DusimagezError: Swift.Error {

    
    
    case InvalidImage(code: String, messageEn: String, messageHi: String
    )
    case UnsupportedFormat(code: String, messageEn: String, messageHi: String
    )
    case ImageTooLarge(code: String, messageEn: String, messageHi: String
    )
    case TargetSizeUnreachable(code: String, messageEn: String, messageHi: String
    )
    case InvalidQuality(code: String, messageEn: String, messageHi: String
    )
    case InvalidDimensions(code: String, messageEn: String, messageHi: String
    )
    case InvalidArgument(code: String, messageEn: String, messageHi: String
    )
    case EmptyInput(code: String, messageEn: String, messageHi: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeDusimagezError: FfiConverterRustBuffer {
    typealias SwiftType = DusimagezError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> DusimagezError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidImage(
            code: try FfiConverterString.read(from: &buf), 
            messageEn: try FfiConverterString.read(from: &buf), 
            messageHi: try FfiConverterString.read(from: &buf)
            )
        case 2: return .UnsupportedFormat(
            code: try FfiConverterString.read(from: &buf), 
            messageEn: try FfiConverterString.read(from: &buf), 
            messageHi: try FfiConverterString.read(from: &buf)
            )
        case 3: return .ImageTooLarge(
            code: try FfiConverterString.read(from: &buf), 
            messageEn: try FfiConverterString.read(from: &buf), 
            messageHi: try FfiConverterString.read(from: &buf)
            )
        case 4: return .TargetSizeUnreachable(
            code: try FfiConverterString.read(from: &buf), 
            messageEn: try FfiConverterString.read(from: &buf), 
            messageHi: try FfiConverterString.read(from: &buf)
            )
        case 5: return .InvalidQuality(
            code: try FfiConverterString.read(from: &buf), 
            messageEn: try FfiConverterString.read(from: &buf), 
            messageHi: try FfiConverterString.read(from: &buf)
            )
        case 6: return .InvalidDimensions(
            code: try FfiConverterString.read(from: &buf), 
            messageEn: try FfiConverterString.read(from: &buf), 
            messageHi: try FfiConverterString.read(from: &buf)
            )
        case 7: return .InvalidArgument(
            code: try FfiConverterString.read(from: &buf), 
            messageEn: try FfiConverterString.read(from: &buf), 
            messageHi: try FfiConverterString.read(from: &buf)
            )
        case 8: return .EmptyInput(
            code: try FfiConverterString.read(from: &buf), 
            messageEn: try FfiConverterString.read(from: &buf), 
            messageHi: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: DusimagezError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidImage(code,messageEn,messageHi):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(code, into: &buf)
            FfiConverterString.write(messageEn, into: &buf)
            FfiConverterString.write(messageHi, into: &buf)
            
        
        case let .UnsupportedFormat(code,messageEn,messageHi):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(code, into: &buf)
            FfiConverterString.write(messageEn, into: &buf)
            FfiConverterString.write(messageHi, into: &buf)
            
        
        case let .ImageTooLarge(code,messageEn,messageHi):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(code, into: &buf)
            FfiConverterString.write(messageEn, into: &buf)
            FfiConverterString.write(messageHi, into: &buf)
            
        
        case let .TargetSizeUnreachable(code,messageEn,messageHi):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(code, into: &buf)
            FfiConverterString.write(messageEn, into: &buf)
            FfiConverterString.write(messageHi, into: &buf)
            
        
        case let .InvalidQuality(code,messageEn,messageHi):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(code, into: &buf)
            FfiConverterString.write(messageEn, into: &buf)
            FfiConverterString.write(messageHi, into: &buf)
            
        
        case let .InvalidDimensions(code,messageEn,messageHi):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(code, into: &buf)
            FfiConverterString.write(messageEn, into: &buf)
            FfiConverterString.write(messageHi, into: &buf)
            
        
        case let .InvalidArgument(code,messageEn,messageHi):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(code, into: &buf)
            FfiConverterString.write(messageEn, into: &buf)
            FfiConverterString.write(messageHi, into: &buf)
            
        
        case let .EmptyInput(code,messageEn,messageHi):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(code, into: &buf)
            FfiConverterString.write(messageEn, into: &buf)
            FfiConverterString.write(messageHi, into: &buf)
            
        }
    }
}


